"use client";

import * as React from "react";
import * as SwitchPrimitive from "@radix-ui/react-switch";
import { cn } from "@/lib/utils";

/**
 * Switch — from the KinetixUI design source, node 54855:13984: 48×24 pill track, off = `--tertiary`, on =
 * `--action`, 20px `--background` thumb that travels 24px, focus = 2px `--ring` offset.
 *
 * It follows the selection-control state contract (TOKENS.md, "Selection controls"): the same 8% / 14%
 * `--foreground` state layer as Checkbox and Radio on hover and press, the on track steps to `--action`/90
 * under the pointer, the thumb's position is the shape cue for on/off, the focus ring cannot be covered by
 * any other layer, and a disabled switch does not answer the pointer. The off track stays `--tertiary`
 * (2.6:1, a tracked SC 1.4.11 exception in check-contrast.mjs): the thumb and `aria-checked` carry it.
 *
 * Motion (MOTION.md, "Switch"): `selection-control`, on purpose not Toggle's or Checkbox's `selection-state`.
 * The thumb's travel, the track colour and the 5px halo all run on `instant` (100ms) `standard`, because the
 * thumb is a physical control that should land with the finger, not a colour settling. `aria-checked` and
 * `data-state` change at once; only paint follows. The reduced-motion `transition-none` on the track and the
 * thumb is for a registry install, which does not get the preset's global floor (check-registry-motion.mjs):
 * without it, such a reader's thumb still slid on Tailwind's default 150ms. (The contract's `expects` look for
 * the full class, so this comment is worded not to satisfy them by itself.)
 */
const Switch = React.forwardRef<
  React.ElementRef<typeof SwitchPrimitive.Root>,
  React.ComponentPropsWithoutRef<typeof SwitchPrimitive.Root>
>(({ className, ...props }, ref) => (
  <SwitchPrimitive.Root
    ref={ref}
    className={cn(
      "peer inline-flex h-6 w-12 shrink-0 cursor-pointer items-center rounded-full border-2 border-transparent",
      "transition-[background-color,box-shadow] duration-instant ease-standard",
      "motion-reduce:transition-none",
      "data-[state=checked]:bg-action data-[state=unchecked]:bg-tertiary",
      "[@media(hover:hover)]:enabled:hover:[box-shadow:0_0_0_5px_hsl(var(--foreground)/0.08)]",
      // Pressed is written twice: bare for touch, and again inside the hover media query, because Tailwind
      // emits media-wrapped utilities after plain ones and the hover layer would otherwise outrank the press.
      "enabled:active:[box-shadow:0_0_0_5px_hsl(var(--foreground)/0.14)]",
      "[@media(hover:hover)]:enabled:active:[box-shadow:0_0_0_5px_hsl(var(--foreground)/0.14)]",
      "[@media(hover:hover)]:enabled:hover:data-[state=checked]:bg-action/90",
      "focus-visible:outline-none focus-visible:!ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
      "disabled:cursor-not-allowed disabled:opacity-disabled",
      className,
    )}
    {...props}
  >
    <SwitchPrimitive.Thumb
      className={cn(
        "pointer-events-none relative block size-5 rounded-full bg-background shadow-lg ring-0",
        // The thumb travels along the INLINE axis of the switch's own direction: `inset-inline-start` is
        // logical, so the browser resolves start against the direction the switch is laid out in — the
        // nearest `dir`, in an LTR section of an RTL page as much as anywhere else. It used to be a physical
        // `translate-x` flipped by `rtl:`, and Tailwind 3's `rtl:` is `[dir=rtl] *` — ANY rtl ancestor — so
        // a switch in an LTR section of an RTL page was flipped too and its thumb landed 22px outside the
        // track, over its own focus ring (check:selection-visual, "direction"). `:dir()` would have been the
        // selector answer, but Vite 8's Lightning CSS lowers `:dir(ltr)` for its default targets to a
        // `:not(:lang(ar, he, …))` guess about the page's LANGUAGE, which broke every RTL switch in the built
        // Storybook — a consumer's toolchain can do the same. A logical property needs no selector at all.
        // The offset is relative, so nothing around the switch reflows while it moves.
        "transition-[inset-inline-start] duration-instant ease-standard",
        "motion-reduce:transition-none",
        "start-0 data-[state=checked]:start-6",
        // Forced colours repaint both the track and the thumb's fill as Canvas and strip the shadow, so the
        // thumb, the only on/off cue, vanished and on read the same as off. A system colour is honoured there.
        "forced-colors:bg-[CanvasText] forced-colors:data-[disabled]:bg-[GrayText]",
      )}
    />
  </SwitchPrimitive.Root>
));
Switch.displayName = SwitchPrimitive.Root.displayName;

export { Switch };

import { type ClassValue, clsx } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

// The Material type-scale utilities (`text-label-md`, `text-body-sm`, …) come
// from `fontSize` in tailwind.config.ts. Without this, tailwind-merge reads them
// as text *colours* and drops a real colour class (`text-primary-foreground`).
const twMerge = extendTailwindMerge({
  extend: {
    classGroups: {
      "font-size": [
        {
          text: [
            "display-lg", "display-md", "display-sm",
            "headline-lg", "headline-md", "headline-sm",
            "title-lg", "title-md", "title-sm", "title-dialog",
            "label-lg", "label-md", "label-sm",
            "body-lg", "body-md", "body-sm",
          ],
        },
      ],
    },
  },
});

/** Merges Tailwind class names, resolving conflicts (clsx + tailwind-merge). */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/**
 * Keeps the keyboard somewhere useful when a control removes the row it lives in.
 *
 * A remove button inside a chip or a list row destroys itself. Nothing then holds focus, so the
 * browser drops it on `<body>` and the next Tab starts again from the top of the document — a
 * keyboard user clearing three chips is sent back to the beginning after each one.
 *
 * Call this from the removing control's own handler, with the control and a selector that matches
 * one peer per removable row. The surviving peer is chosen BEFORE the removal, from document order:
 * the next row's control, or the previous one when the last row goes. It is focused once the
 * removal has actually happened AND left the keyboard stranded — so a handler
 * that removes nothing, or that moves focus somewhere of its own, keeps the focus it chose.
 *
 * @param trigger the control that was activated
 * @param peerSelector a selector matching the equivalent control on every row, e.g. "[data-kx-remove]"
 * @param options.scope where to look for peers; defaults to the trigger's parent list or its document
 * @param options.fallback where to go when no row survives — a chip group's own input, say
 *
 * Limit: the removal is expected to commit within a microtask or the next animation frame, which is
 * what a React state update from a click does. A removal awaited behind a network call lands later
 * than that, and its focus is the caller's to manage.
 */
export function focusAfterRemoval(
  trigger: HTMLElement | null | undefined,
  peerSelector: string,
  options: { scope?: HTMLElement | null; fallback?: HTMLElement | null } = {},
): void {
  if (!trigger?.isConnected) return;
  const scope = options.scope ?? trigger.closest("ul, ol, [data-kx-removable-group]") ?? trigger.ownerDocument.body;
  const peers = Array.from(scope.querySelectorAll<HTMLElement>(peerSelector));
  const here = peers.indexOf(trigger);
  const survivor = here < 0 ? null : (peers[here + 1] ?? peers[here - 1] ?? null);
  const target = survivor ?? options.fallback ?? null;
  if (!target) return;

  const settle = () => {
    // The trigger is still there: nothing was removed, so nothing should move.
    if (trigger.isConnected) return false;
    // And step in only where the removal actually stranded the keyboard. A handler that moved focus
    // somewhere of its own — the input a chip group is typed into, say — made a deliberate choice,
    // and that choice wins. Stranded means focus fell back to the document, which is what a browser
    // does when the focused element is taken out of the tree.
    const doc = trigger.ownerDocument;
    const active = doc.activeElement;
    const stranded = !active || active === doc.body || active === doc.documentElement || !active.isConnected;
    if (!stranded) return true;
    if (target.isConnected) target.focus();
    return true;
  };
  queueMicrotask(() => {
    if (settle()) return;
    if (typeof requestAnimationFrame === "function") requestAnimationFrame(settle);
  });
}
